import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.QWVCgkrI.js";const d=JSON.parse('{"title":"ゲーム開発・エンジン・現場の言い回しの用語集","description":"","frontmatter":{"title":"ゲーム開発・エンジン・現場の言い回しの用語集","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"reference","format":"glossary","domain":"terms","summary":"ゲーム開発・エンジン・現場の言い回しで使う語の定義、用例、関連する解説記事。"}},"headers":[],"relativePath":"glossary/game.md","filePath":"glossary/game.md"}'),n={name:"glossary/game.md"};function s(g,e,l,p,i,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="ゲーム開発・エンジン・現場の言い回しの用語集" tabindex="-1">ゲーム開発・エンジン・現場の言い回しの用語集 <a class="header-anchor" href="#ゲーム開発・エンジン・現場の言い回しの用語集" aria-label="Permalink to &quot;ゲーム開発・エンジン・現場の言い回しの用語集&quot;">​</a></h1><p><a href="/study/glossary/">用語集の入口・全用語検索</a></p><p>読み順で 53 項目を掲載しています。</p><h2 id="asset" tabindex="-1">アセット <a class="header-anchor" href="#asset" aria-label="Permalink to &quot;アセット {#asset}&quot;">​</a></h2><p><strong>asset</strong> ／ 読み あせっと</p><p>ゲーム制作や実行に使う素材・データ。画像、モデル、音声、シーンや材質の設定などが含まれる。</p><p><strong>例</strong>　足音のアセットを差し替える。</p><p><strong>関連</strong>　<a href="/study/game/asset-loading.html">実行時のアセットロード</a> · <a href="/study/glossary/game.html#import">インポート</a> · <a href="/study/glossary/game.html#load">ロード</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/AssetWorkflow.html" target="_blank" rel="noreferrer">Unity 6.3 — Introduction to assets</a></p><h2 id="alpha-beta" tabindex="-1">α版・β版 <a class="header-anchor" href="#alpha-beta" aria-label="Permalink to &quot;α版・β版 {#alpha-beta}&quot;">​</a></h2><p><strong>alpha / beta</strong> ／ 読み あるふぁばん べーたばん あるふぁべーた</p><p>正式版より前のビルドや開発段階の呼び名。主要機能を入れて通して遊べる段階をα版とし、内容がそろい、不具合修正やバランス調整に集中する段階をβ版とする例がある。</p><p><strong>この分野での意味</strong>　機能やコンテンツの到達条件とテスト参加者の範囲は、プロジェクトごとに決める。β版にも限定公開と一般公開がある。</p><p><strong>例</strong>　β版を配って実機での問題を集める。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#feature-freeze">フィーチャーフリーズ</a> · <a href="/study/glossary/game.html#build-number">ビルド番号</a></p><p><strong>出典</strong>　<a href="https://www.ubisoft.com/en-us/company/how-we-make-games/creative-process" target="_blank" rel="noreferrer">Ubisoft — Creative Process（Alpha・Betaの到達条件の例）</a></p><h2 id="unload" tabindex="-1">アンロード <a class="header-anchor" href="#unload" aria-label="Permalink to &quot;アンロード {#unload}&quot;">​</a></h2><p><strong>unload / unloading</strong> ／ 読み あんろーど</p><p>シーンやアセットの利用を終了し、使用中の参照を外して資源を解放できる状態にすること。</p><p><strong>この分野での意味</strong>　他の利用者が同じ資源を参照している場合は、メモリに残ることがある。</p><p><strong>例</strong>　ダンジョンを出たらその区画をアンロードする。</p><p><strong>関連</strong>　<a href="/study/game/asset-loading.html">実行時のアセットロード</a> · <a href="/study/glossary/game.html#load">ロード</a> · <a href="/study/glossary/game.html#streaming">ストリーミング</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/level-streaming-overview-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Level Streaming Overview（UE 5.8）</a></p><h2 id="import" tabindex="-1">インポート <a class="header-anchor" href="#import" aria-label="Permalink to &quot;インポート {#import}&quot;">​</a></h2><p><strong>import</strong> ／ 読み いんぽーと</p><p>外部で作ったファイルを制作環境へ取り込み、その環境で使えるデータに変換すること。</p><p><strong>この分野での意味</strong>　実行中に使うためのロードとは工程が異なる。</p><p><strong>例</strong>　FBXをインポートしてスケールを確認する。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/game.html#cook">クック</a> · <a href="/study/glossary/game.html#load">ロード</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/AssetWorkflow.html" target="_blank" rel="noreferrer">Unity 6.3 — Introduction to assets</a></p><h2 id="gc" tabindex="-1">ガベコレ <a class="header-anchor" href="#gc" aria-label="Permalink to &quot;ガベコレ {#gc}&quot;">​</a></h2><p><strong>GC / Garbage Collection</strong> ／ 読み がべこれ がべーじこれくしょん じーしー</p><p>プログラムから到達できなくなったオブジェクトのメモリを回収する仕組み。</p><p><strong>例</strong>　一時オブジェクトの割り当てを減らしてガベコレの頻度を下げる。</p><p><strong>関連</strong>　<a href="/study/languages/csharp/memory-management-vs-gc.html">C++とC#のメモリ管理</a> · <a href="/study/glossary/game.html#gc-spike">GCスパイク</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/performance-incremental-garbage-collection.html" target="_blank" rel="noreferrer">Unity 6.3 — Garbage collection modes</a></p><h2 id="qa" tabindex="-1">QA <a class="header-anchor" href="#qa" aria-label="Permalink to &quot;QA {#qa}&quot;">​</a></h2><p><strong>QA / Quality Assurance</strong> ／ 読み きゅーえー ひんしつほしょう</p><p>品質を確保するための活動。ゲーム開発の会話では、テスト計画、再現、修正確認などを行うチームや担当を指すこともある。</p><p><strong>例</strong>　QAが古いセーブを使って修正を確認する。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/game.html#regression">リグレッション</a> · <a href="/study/glossary/game.html#lot-check">ロットチェック</a></p><p><strong>出典</strong>　<a href="https://istqb.org/wp-content/uploads/2024/11/ISTQB_CTFL_Syllabus_v4.0.1.pdf" target="_blank" rel="noreferrer">ISTQB — Certified Tester Foundation Level Syllabus 4.0.1</a> · <a href="https://www.nintendo.co.jp/jobs/keyword/154.html" target="_blank" rel="noreferrer">任天堂 — ゲームソフト適合性検査とロットチェック</a></p><h2 id="cook" tabindex="-1">クック <a class="header-anchor" href="#cook" aria-label="Permalink to &quot;クック {#cook}&quot;">​</a></h2><p><strong>cook / cooking</strong> ／ 読み くっく</p><p>Unreal Engine 5.8で、エディター用のアセットを対象プラットフォームの実行時に使える形式へ変換する工程。</p><p><strong>この分野での意味</strong>　Houdiniではノードの評価を指す。</p><p><strong>例</strong>　対象のゲーム機向けにテクスチャをクックする。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/game.html#houdini-cook">クック（Houdini）</a> · <a href="/study/glossary/game.html#packaging">パッケージング</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/packaging-your-project" target="_blank" rel="noreferrer">Epic Games — Packaging Your Project（UE 5.8）</a></p><h2 id="houdini-cook" tabindex="-1">クック（Houdini） <a class="header-anchor" href="#houdini-cook" aria-label="Permalink to &quot;クック（Houdini） {#houdini-cook}&quot;">​</a></h2><p><strong>cook / cooking</strong> ／ 読み くっく ふーでぃに</p><p>Houdini 22.0で、依存するノードを評価し、入力や現在のフレームに対応する出力を作ること。</p><p><strong>この分野での意味</strong>　UEでのクックは、対象機種に合わせたアセット変換。</p><p><strong>例</strong>　パラメーターを変えるとノードが再クックされる。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#cook">クック</a></p><p><strong>出典</strong>　<a href="https://www.sidefx.com/docs/houdini/basics/cooking.html" target="_blank" rel="noreferrer">SideFX — Cooking（Houdini 22.0）</a></p><h2 id="game-feel" tabindex="-1">ゲームフィール・手触り <a class="header-anchor" href="#game-feel" aria-label="Permalink to &quot;ゲームフィール・手触り {#game-feel}&quot;">​</a></h2><p><strong>game feel</strong> ／ 読み げーむふぃーる てざわり</p><p>操作に対して返る動きや映像・音などを通じてプレイヤーが感じる操作感。</p><p><strong>例</strong>　停止時の減速を調整して手触りを確かめる。</p><p><strong>関連</strong>　<a href="/study/game/camera-system.html">カメラシステム</a> · <a href="/study/glossary/game.html#hit-stop">ヒットストップ</a> · <a href="/study/glossary/game.html#core-loop">コアループ</a></p><p><strong>出典</strong>　<a href="https://www.gamedeveloper.com/game-platforms/feature-game-feel---the-secret-ingredient-" target="_blank" rel="noreferrer">Steve Swink — Game Feel: The Secret Ingredient</a></p><h2 id="game-loop" tabindex="-1">ゲームループ <a class="header-anchor" href="#game-loop" aria-label="Permalink to &quot;ゲームループ {#game-loop}&quot;">​</a></h2><p><strong>game loop</strong> ／ 読み げーむるーぷ</p><p>入力の取り込み、状態更新、描画などを実行中に繰り返す処理の構造。</p><p><strong>例</strong>　ゲームループで入力を取り込み、固定tickで状態を進める。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a> · <a href="/study/glossary/game.html#core-loop">コアループ</a> · <a href="/study/glossary/game.html#frame">フレーム</a> · <a href="/study/glossary/game.html#tick">ティック</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/execution-order.html" target="_blank" rel="noreferrer">Unity 6.3 — Event function execution order</a></p><h2 id="core-loop" tabindex="-1">コアループ <a class="header-anchor" href="#core-loop" aria-label="Permalink to &quot;コアループ {#core-loop}&quot;">​</a></h2><p><strong>core loop / core gameplay loop</strong> ／ 読み こあるーぷ</p><p>プレイヤーが繰り返す中心的な行動と、その結果から次の行動へ戻る流れ。</p><p><strong>この分野での意味</strong>　フレームごとに回るプログラムのゲームループとは、繰り返す主体が異なる。</p><p><strong>例</strong>　探索し、素材を集め、装備を作ってまた探索へ出る。</p><p><strong>関連</strong>　<a href="/study/game/shooter-design.html">シューティングゲームの設計</a> · <a href="/study/glossary/game.html#game-feel">ゲームフィール・手触り</a> · <a href="/study/glossary/game.html#game-loop">ゲームループ</a></p><p><strong>出典</strong>　<a href="https://www.gamedeveloper.com/design/how-supporting-core-loops-and-early-prototyping-are-key-to-your-game-s-success" target="_blank" rel="noreferrer">Game Developer — How supporting core loops and early prototyping are key to your game’s success</a></p><h2 id="content-freeze" tabindex="-1">コンテンツフリーズ <a class="header-anchor" href="#content-freeze" aria-label="Permalink to &quot;コンテンツフリーズ {#content-freeze}&quot;">​</a></h2><p><strong>content freeze</strong> ／ 読み こんてんつふりーず</p><p>ステージ、台詞、素材など、ゲーム内容の追加・変更を原則止める期間・区切り。</p><p><strong>この分野での意味</strong>　新機能を止めるフィーチャーフリーズと対象が異なる。</p><p><strong>例</strong>　翻訳検証のため、台詞のコンテンツフリーズを設定する。</p><p><strong>関連</strong>　<a href="/study/game/localization-design.html">ローカライズの設計</a> · <a href="/study/glossary/game.html#feature-freeze">フィーチャーフリーズ</a></p><h2 id="gc-spike" tabindex="-1">GCスパイク <a class="header-anchor" href="#gc-spike" aria-label="Permalink to &quot;GCスパイク {#gc-spike}&quot;">​</a></h2><p><strong>GC spike / Garbage Collection spike</strong> ／ 読み じーしーすぱいく がべこれすぱいく</p><p>ガベージコレクションの処理により、フレーム時間などが一時的に増える現象。</p><p><strong>この分野での意味</strong>　割り当て量の表示と、GCそのものにかかった時間は別。</p><p><strong>例</strong>　プロファイラーで長いフレームにGCスパイクがあるか見る。</p><p><strong>関連</strong>　<a href="/study/tools/profiling/cpu-profiling.html">CPUプロファイリング</a> · <a href="/study/glossary/game.html#gc">ガベコレ</a> · <a href="/study/glossary/game.html#spike">スパイク</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/performance-incremental-garbage-collection.html" target="_blank" rel="noreferrer">Unity 6.3 — Garbage collection modes</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ProfilerCPU.html" target="_blank" rel="noreferrer">Unity 6.3 — CPU Usage Profiler module</a></p><h2 id="scene" tabindex="-1">シーン <a class="header-anchor" href="#scene" aria-label="Permalink to &quot;シーン {#scene}&quot;">​</a></h2><p><strong>scene</strong> ／ 読み しーん</p><p>Unityで、ある場面のGameObjectの配置や環境を保存する単位。複数のシーンを同時に読み込める。</p><p><strong>例</strong>　タイトル画面と対戦を別シーンにする。</p><p><strong>関連</strong>　<a href="/study/game/basics/scenes-and-components.html">シーン・オブジェクト・コンポーネント</a> · <a href="/study/glossary/game.html#level">レベル</a> · <a href="/study/glossary/game.html#streaming">ストリーミング</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/CreatingScenes.html" target="_blank" rel="noreferrer">Unity 6.3 — Introduction to scenes</a></p><h2 id="shader" tabindex="-1">シェーダー（エンジン内の呼び方） <a class="header-anchor" href="#shader" aria-label="Permalink to &quot;シェーダー（エンジン内の呼び方） {#shader}&quot;">​</a></h2><p><strong>shader / shader asset</strong> ／ 読み しぇーだー しぇーだ</p><p>エンジンの会話で、GPUプログラムや、それをまとめるシェーダー資産を指す語。材質の設定まで含めてこう呼ぶこともある。</p><p><strong>この分野での意味</strong>　UnityではShaderと、そのプロパティー値を持つMaterialを区別する。</p><p><strong>例</strong>　水面のシェーダーを差し替える。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a> · <a href="/study/glossary/graphics.html#shader">シェーダー</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Materials.html" target="_blank" rel="noreferrer">Unity 6.3 — Materials and shaders</a></p><h2 id="slowdown" tabindex="-1">処理落ち <a class="header-anchor" href="#slowdown" aria-label="Permalink to &quot;処理落ち {#slowdown}&quot;">​</a></h2><p><strong>slowdown</strong> ／ 読み しょりおち</p><p>仕事が所定の時間内に終わらず、表示やゲームの進行が遅くなることを指す現場語。</p><p><strong>この分野での意味</strong>　固定tickなどで時間を管理していると、表示のカクつきとゲーム内時間の遅れは別に起きる。</p><p><strong>例</strong>　敵を出しすぎて処理落ちする。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a> · <a href="/study/glossary/game.html#frame-drop">フレーム落ち</a></p><h2 id="streaming" tabindex="-1">ストリーミング <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;ストリーミング {#streaming}&quot;">​</a></h2><p><strong>streaming</strong> ／ 読み すとりーみんぐ</p><p>プレイ中の必要性に応じて、世界の一部やテクスチャなどを順次読み込み、不要になった分を解放する方式。</p><p><strong>この分野での意味</strong>　動画の配信を指す場合もある。</p><p><strong>例</strong>　プレイヤーの移動に合わせて地形をストリーミングする。</p><p><strong>関連</strong>　<a href="/study/game/world-streaming.html">ワールドストリーミング</a> · <a href="/study/glossary/game.html#load">ロード</a> · <a href="/study/glossary/game.html#unload">アンロード</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/level-streaming-overview-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Level Streaming Overview（UE 5.8）</a></p><h2 id="spike" tabindex="-1">スパイク <a class="header-anchor" href="#spike" aria-label="Permalink to &quot;スパイク {#spike}&quot;">​</a></h2><p><strong>spike</strong> ／ 読み すぱいく</p><p>計測した時間や使用量が、一時的に周囲の値より大きくなること。</p><p><strong>例</strong>　初回のエフェクト再生でCPU時間のスパイクが出る。</p><p><strong>関連</strong>　<a href="/study/tools/profiling/cpu-profiling.html">CPUプロファイリング</a> · <a href="/study/glossary/game.html#hitch">ヒッチ</a> · <a href="/study/glossary/game.html#gc-spike">GCスパイク</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ProfilerCPU.html" target="_blank" rel="noreferrer">Unity 6.3 — CPU Usage Profiler module</a></p><h2 id="spawn" tabindex="-1">スポーン <a class="header-anchor" href="#spawn" aria-label="Permalink to &quot;スポーン {#spawn}&quot;">​</a></h2><p><strong>spawn</strong> ／ 読み すぽーん</p><p>実行中にゲーム内のオブジェクトを生成し、ワールドへ登場させること。</p><p><strong>この分野での意味</strong>　プールから既存の実体を取り出して再登場させる場合にも使う。</p><p><strong>例</strong>　敵を画面外の地点にスポーンする。</p><p><strong>関連</strong>　<a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブと生成・破棄の基本</a> · <a href="/study/glossary/game.html#despawn">デスポーン</a> · <a href="/study/glossary/game.html#prefab">プレハブ</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/spawning-actors-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Spawning Actors（UE 5.8）</a></p><h2 id="generational-handle" tabindex="-1">世代付きハンドル <a class="header-anchor" href="#generational-handle" aria-label="Permalink to &quot;世代付きハンドル {#generational-handle}&quot;">​</a></h2><p><strong>generational handle</strong> ／ 読み せだいつきはんどる</p><p>スロット番号と世代番号を組み合わせ、同じスロットに入った別の実体を区別する参照用の値。</p><p><strong>例</strong>　敵の古いハンドルは世代が違うため無効になる。</p><p><strong>関連</strong>　<a href="/study/algorithms/generational-handles.html">世代付きハンドル</a> · <a href="/study/glossary/pc.html#handle">ハンドル</a> · <a href="/study/glossary/graphics.html#handle">ハンドル（制作ツール）</a></p><p><strong>出典</strong>　<a href="https://docs.rs/bevy/latest/bevy/ecs/entity/struct.EntityGeneration.html" target="_blank" rel="noreferrer">Bevy — EntityGeneration</a></p><h2 id="cheat" tabindex="-1">チート <a class="header-anchor" href="#cheat" aria-label="Permalink to &quot;チート {#cheat}&quot;">​</a></h2><p><strong>cheat / debug cheat</strong> ／ 読み ちーと</p><p>通常のゲームルールを迂回する操作。制作時は、無敵化やステージ移動などの検証用コマンドにも使う。</p><p><strong>この分野での意味</strong>　対戦で許可なく使う不正行為とは、許可された用途が違う。</p><p><strong>例</strong>　再現テスト用のチートで必要なアイテムを付与する。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#debug-menu">デバッグメニュー</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/API/Runtime/Engine/UCheatManager" target="_blank" rel="noreferrer">Epic Games — UCheatManager（UE 5.8）</a></p><h2 id="toolchain" tabindex="-1">ツールチェーン <a class="header-anchor" href="#toolchain" aria-label="Permalink to &quot;ツールチェーン {#toolchain}&quot;">​</a></h2><p><strong>toolchain</strong> ／ 読み つーるちぇーん</p><p>ソースや素材を成果物にするために、組み合わせて使うツール群。コンパイラ、リンカー、SDKのツール、アセット変換ツールなどが該当する。</p><p><strong>例</strong>　機種ごとに同じ版のツールチェーンをCIで使う。</p><p><strong>関連</strong>　<a href="/study/compilers/libraries-apis-and-sdks.html">ライブラリ・API・SDK</a> · <a href="/study/glossary/game.html#pipeline">パイプライン（制作）</a> · <a href="/study/glossary/game.html#workflow">ワークフロー</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/build-operations-cooking-packaging-deploying-and-running-projects-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Build Operations（UE 5.8）</a></p><h2 id="trc" tabindex="-1">TRC <a class="header-anchor" href="#trc" aria-label="Permalink to &quot;TRC {#trc}&quot;">​</a></h2><p><strong>Technical Requirements Checklist</strong> ／ 読み てぃーあーるしー</p><p>PlayStationのソフト提出時に使われてきた、技術要件のチェックリスト。PC向けの品質検査などでも同じ略語を使う例がある。</p><p><strong>この分野での意味</strong>　Xboxの現行文書ではXbox Requirements（XR）、Xbox 360時代の資料ではTechnical Certification Requirements（TCR）と呼ぶ。任天堂ではガイドラインへの適合を確認する工程をロットチェックと呼ぶ。</p><p><strong>例</strong>　コントローラーを抜いたときの挙動をTRCに沿って確認する。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#lot-check">ロットチェック</a></p><p><strong>出典</strong>　<a href="https://ir.take2games.com/static-files/1c0445c6-016b-41f7-97bc-03274e8f3fa3" target="_blank" rel="noreferrer">SCEA・Take-Two — PlayStationライセンス契約 §4.5</a> · <a href="https://developer.download.nvidia.com/assets/gameworks/downloads/regular/GDC17/WD2_Success_Story_with%20_NVIDIA-GDC_2017-Final.pdf#page=10" target="_blank" rel="noreferrer">Ubisoft・NVIDIA — Watch Dogs 2: PC Adaptation（GDC 2017）</a> · <a href="https://learn.microsoft.com/en-us/gaming/gdk/docs/store/policies/console/console-certification-requirements-and-tests?view=gdk-2610" target="_blank" rel="noreferrer">Microsoft — Xbox Requirements（GDK 2610）</a> · <a href="https://www.gamedeveloper.com/business/sponsored-feature-xna-game-quality-the-certification-story" target="_blank" rel="noreferrer">Microsoft XNA Game Quality — Xbox 360認証の解説</a> · <a href="https://www.nintendo.co.jp/jobs/keyword/154.html" target="_blank" rel="noreferrer">任天堂 — ゲームソフト適合性検査とロットチェック</a></p><h2 id="tick" tabindex="-1">ティック <a class="header-anchor" href="#tick" aria-label="Permalink to &quot;ティック {#tick}&quot;">​</a></h2><p><strong>tick</strong> ／ 読み てぃっく</p><p>シミュレーションやオブジェクトを一回更新する単位。固定tickのゲームでは、描画間隔と別に更新の刻みを決める。</p><p><strong>この分野での意味</strong>　Unreal EngineのActor Tickには、フレームごとや指定間隔で呼ぶ設定がある。</p><p><strong>例</strong>　サーバーは毎秒60ティック進める。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a> · <a href="/study/glossary/game.html#frame">フレーム</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/actor-ticking-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Actor Ticking（UE 5.8）</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/execution-order.html" target="_blank" rel="noreferrer">Unity 6.3 — Event function execution order</a></p><h2 id="director" tabindex="-1">ディレクター <a class="header-anchor" href="#director" aria-label="Permalink to &quot;ディレクター {#director}&quot;">​</a></h2><p><strong>game director</strong> ／ 読み でぃれくたー</p><p>ゲームの方向性や体験を決め、各担当の成果をその方向へそろえる役割。</p><p><strong>この分野での意味</strong>　意思決定の範囲や、プロデューサーとの分担はチームによる。</p><p><strong>例</strong>　ディレクターが試作の操作感を確認する。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#planner">プランナー</a> · <a href="/study/glossary/game.html#game-feel">ゲームフィール・手触り</a></p><p><strong>出典</strong>　<a href="https://www.nintendo.co.jp/wii/interview/sx3j/vol1/index.html" target="_blank" rel="noreferrer">任天堂 — 社長が訊く『パンドラの塔』（ディレクターの担当）</a></p><h2 id="technical-artist" tabindex="-1">テクニカルアーティスト <a class="header-anchor" href="#technical-artist" aria-label="Permalink to &quot;テクニカルアーティスト {#technical-artist}&quot;">​</a></h2><p><strong>TA / Technical Artist</strong> ／ 読み てくにかるあーてぃすと てぃーえー</p><p>アート制作と実装を技術面でつなぐ職種。ツール、シェーダー、リグ、最適化など、担当範囲はチームで変わる。</p><p><strong>例</strong>　TAとモデルのLOD生成手順を調整する。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/overview.html">シェーダー言語の全体像</a> · <a href="/study/glossary/game.html#pipeline">パイプライン（制作）</a></p><p><strong>出典</strong>　<a href="https://www.ubisoft.com/en-us/company/careers/search/744000110207267-senior-technical-artist-tool-art-pipelines-w-m-nb-" target="_blank" rel="noreferrer">Ubisoft — Technical Artistの職務紹介</a></p><h2 id="despawn" tabindex="-1">デスポーン <a class="header-anchor" href="#despawn" aria-label="Permalink to &quot;デスポーン {#despawn}&quot;">​</a></h2><p><strong>despawn</strong> ／ 読み ですぽーん</p><p>オブジェクトをワールドから取り除き、その個体としての活動を終えること。</p><p><strong>この分野での意味</strong>　実体を破棄するか、無効にして再利用するかは実装による。</p><p><strong>例</strong>　画面外へ出た弾をデスポーンしてプールに返す。</p><p><strong>関連</strong>　<a href="/study/game/patterns/object-pool.html">オブジェクトプール</a> · <a href="/study/glossary/game.html#spawn">スポーン</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/unreal-engine-actor-lifecycle" target="_blank" rel="noreferrer">Epic Games — Actor Lifecycle（UE 5.8）</a></p><h2 id="debug-menu" tabindex="-1">デバッグメニュー <a class="header-anchor" href="#debug-menu" aria-label="Permalink to &quot;デバッグメニュー {#debug-menu}&quot;">​</a></h2><p><strong>debug menu</strong> ／ 読み でばっぐめにゅー</p><p>ステージ移動、状態表示、再現用設定などを操作する、開発・検証向けの画面。</p><p><strong>例</strong>　デバッグメニューからボス戦に直接入る。</p><p><strong>関連</strong>　<a href="/study/tools/development-tools-basics.html">開発ツールの基本</a> · <a href="/study/glossary/game.html#cheat">チート</a> · <a href="/study/glossary/game.html#qa">QA</a></p><h2 id="pipeline" tabindex="-1">パイプライン（制作） <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;パイプライン（制作） {#pipeline}&quot;">​</a></h2><p><strong>asset pipeline / content pipeline</strong> ／ 読み ぱいぷらいん せいさく</p><p>制作した素材を検査・変換し、ゲームで使えるデータにして配布へ渡す工程のつながり。</p><p><strong>この分野での意味</strong>　GPUの描画段階を指すパイプラインとは対象が異なる。</p><p><strong>例</strong>　モデルの命名検査をアセットパイプラインへ組み込む。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/graphics.html#pipeline">描画パイプライン</a> · <a href="/study/glossary/game.html#workflow">ワークフロー</a> · <a href="/study/glossary/game.html#toolchain">ツールチェーン</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/packaging-your-project" target="_blank" rel="noreferrer">Epic Games — Packaging Your Project（UE 5.8）</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/AssetWorkflow.html" target="_blank" rel="noreferrer">Unity 6.3 — Introduction to assets</a></p><h2 id="budget" tabindex="-1">バジェット（予算） <a class="header-anchor" href="#budget" aria-label="Permalink to &quot;バジェット（予算） {#budget}&quot;">​</a></h2><p><strong>budget / frame budget</strong> ／ 読み ばじぇっと よさん</p><p>フレーム時間、メモリ、描画や転送などに割り当てる許容量。60 Hzで1表示間隔に使える時間は約16.67 ms。</p><p><strong>この分野での意味</strong>　CPU・GPUが並行する場合、各処理時間を単純に足すだけでは表示間隔を求められない。</p><p><strong>例</strong>　CPUのフレーム予算にロード処理が収まらない。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a> · <a href="/study/glossary/game.html#hot-path">ホットパス</a> · <a href="/study/glossary/game.html#frame">フレーム</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ProfilerCPU.html" target="_blank" rel="noreferrer">Unity 6.3 — CPU Usage Profiler module</a></p><h2 id="packaging" tabindex="-1">パッケージング <a class="header-anchor" href="#packaging" aria-label="Permalink to &quot;パッケージング {#packaging}&quot;">​</a></h2><p><strong>packaging</strong> ／ 読み ぱっけーじんぐ</p><p>コードと変換済みデータを実行・配布できる形にまとめる工程。UE 5.8のパッケージング全体にはビルド、クック、ステージ、パッケージなどの段階がある。</p><p><strong>例</strong>　テスト端末に入れるためにパッケージングする。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/game.html#cook">クック</a> · <a href="/study/glossary/game.html#build">ビルド（成果物）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/packaging-your-project" target="_blank" rel="noreferrer">Epic Games — Packaging Your Project（UE 5.8）</a></p><h2 id="patch" tabindex="-1">パッチ（ゲーム更新） <a class="header-anchor" href="#patch" aria-label="Permalink to &quot;パッチ（ゲーム更新） {#patch}&quot;">​</a></h2><p><strong>patch / game update</strong> ／ 読み ぱっち</p><p>すでに配布したゲームに、修正や新しいデータを適用する更新。更新の配送には差分やファイル単位の置き換えなどを使う。</p><p><strong>例</strong>　進行不能になる不具合をパッチで直す。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/programming.html#patch">パッチ</a> · <a href="/study/glossary/game.html#build">ビルド（成果物）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/cooking-content-and-creating-chunks-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Cooking Content and Creating Chunks（UE 5.8）</a></p><h2 id="hitch" tabindex="-1">ヒッチ <a class="header-anchor" href="#hitch" aria-label="Permalink to &quot;ヒッチ {#hitch}&quot;">​</a></h2><p><strong>hitch / hitching</strong> ／ 読み ひっち</p><p>一部のフレームだけ長くかかり、動きや入力への反応が一瞬止まったように見えること。</p><p><strong>この分野での意味</strong>　スパイクはグラフの突出、ヒッチはプレイ中に感じる現象を表すことが多い。</p><p><strong>例</strong>　エリア境界を越えるとヒッチする。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a> · <a href="/study/glossary/game.html#spike">スパイク</a> · <a href="/study/glossary/game.html#frame-drop">フレーム落ち</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/stat-commands-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Stat Commands（UE 5.8）</a></p><h2 id="hit-stop" tabindex="-1">ヒットストップ <a class="header-anchor" href="#hit-stop" aria-label="Permalink to &quot;ヒットストップ {#hit-stop}&quot;">​</a></h2><p><strong>hit stop / hitstop</strong> ／ 読み ひっとすとっぷ</p><p>攻撃が当たった瞬間に、一部または全体の動きを短く止めて打撃を強調する演出。</p><p><strong>この分野での意味</strong>　全体の時間スケールを変える方法と、対象ごとに止める方法がある。</p><p><strong>例</strong>　重い攻撃だけヒットストップを長くする。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a> · <a href="/study/glossary/game.html#game-feel">ゲームフィール・手触り</a> · <a href="/study/glossary/game.html#tick">ティック</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/ScriptReference/Time-timeScale.html" target="_blank" rel="noreferrer">Unity 6.3 — Time.timeScale</a> · <a href="https://dev.epicgames.com/community/learning/tutorials/Wv1y/unreal-engine-how-to-make-a-combat-system-in-ue5" target="_blank" rel="noreferrer">Evans Bohl — How to Make a Combat System in UE5（UE 5.7の実装例）</a></p><h2 id="build" tabindex="-1">ビルド（成果物） <a class="header-anchor" href="#build" aria-label="Permalink to &quot;ビルド（成果物） {#build}&quot;">​</a></h2><p><strong>build / game build</strong> ／ 読み びるど せいかぶつ</p><p>ある時点のソースとデータから作られた、試遊・検査・配布に使うゲームの一式。</p><p><strong>この分野での意味</strong>　作る工程を指す「ビルド」と、出来上がった一式を指す「ビルド」がある。</p><p><strong>例</strong>　最新ビルドで不具合を再現する。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/game.html#build-number">ビルド番号</a> · <a href="/study/glossary/game.html#rom">ROM（ロム）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/build-operations-cooking-packaging-deploying-and-running-projects-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Build Operations（UE 5.8）</a></p><h2 id="build-number" tabindex="-1">ビルド番号 <a class="header-anchor" href="#build-number" aria-label="Permalink to &quot;ビルド番号 {#build-number}&quot;">​</a></h2><p><strong>build number</strong> ／ 読み びるどばんごう</p><p>実行ファイルやパッケージを作った版を識別する番号。プレイヤー向けのバージョン表記と別に管理できる。</p><p><strong>この分野での意味</strong>　番号の形式・増加条件は配布先や運用で異なる。</p><p><strong>例</strong>　報告にビルド番号を添えて再現した版を特定する。</p><p><strong>関連</strong>　<a href="/study/tools/ci-and-build-automation.html">CIとビルド自動化</a> · <a href="/study/glossary/game.html#build">ビルド（成果物）</a></p><p><strong>出典</strong>　<a href="https://developer.apple.com/documentation/bundleresources/information-property-list/cfbundleversion" target="_blank" rel="noreferrer">Apple — CFBundleVersion</a></p><h2 id="feature-freeze" tabindex="-1">フィーチャーフリーズ <a class="header-anchor" href="#feature-freeze" aria-label="Permalink to &quot;フィーチャーフリーズ {#feature-freeze}&quot;">​</a></h2><p><strong>feature freeze</strong> ／ 読み ふぃーちゃーふりーず</p><p>新しい機能の追加を原則止め、既存機能の修正や安定化を優先する期間・区切り。</p><p><strong>この分野での意味</strong>　例外や許す修正の範囲はプロジェクトで決める。</p><p><strong>例</strong>　フィーチャーフリーズ後は不具合修正を優先する。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#content-freeze">コンテンツフリーズ</a> · <a href="/study/glossary/game.html#alpha-beta">α版・β版</a></p><p><strong>出典</strong>　<a href="https://github.com/python/devguide/blob/main/developer-workflow/development-cycle.rst" target="_blank" rel="noreferrer">Python Developer’s Guide — Development cycle</a></p><h2 id="boot-sequence" tabindex="-1">ブートシーケンス（ゲーム） <a class="header-anchor" href="#boot-sequence" aria-label="Permalink to &quot;ブートシーケンス（ゲーム） {#boot-sequence}&quot;">​</a></h2><p><strong>boot sequence / game startup</strong> ／ 読み ぶーとしーけんす きどう</p><p>ゲームが起動し、必要なシステムや設定を初期化して、タイトル画面など最初の状態へ進むまでの流れ。</p><p><strong>例</strong>　ブートシーケンスでセーブと初期アセットを読み込む。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-engine-basics.html">ゲームエンジンの役割</a> · <a href="/study/glossary/pc.html#boot">ブート</a> · <a href="/study/glossary/game.html#load">ロード</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/execution-order.html" target="_blank" rel="noreferrer">Unity 6.3 — Event function execution order</a></p><h2 id="planner" tabindex="-1">プランナー <a class="header-anchor" href="#planner" aria-label="Permalink to &quot;プランナー {#planner}&quot;">​</a></h2><p><strong>game designer / game planner</strong> ／ 読み ぷらんなー</p><p>ルール、ステージ、体験など、遊びの内容を設計し、試作や調整を通じて形にする職種。</p><p><strong>この分野での意味</strong>　英語の職名や担当範囲はチームごとに異なる。</p><p><strong>例</strong>　プランナーと敵の行動の切り替え条件を決める。</p><p><strong>関連</strong>　<a href="/study/game/shooter-design.html">シューティングゲームの設計</a> · <a href="/study/glossary/game.html#director">ディレクター</a> · <a href="/study/glossary/game.html#core-loop">コアループ</a></p><p><strong>出典</strong>　<a href="https://www.nintendo.co.jp/jobs/introduction/planning/career.html" target="_blank" rel="noreferrer">任天堂 — 制作企画系の職種紹介</a></p><h2 id="blueprint" tabindex="-1">ブループリント <a class="header-anchor" href="#blueprint" aria-label="Permalink to &quot;ブループリント {#blueprint}&quot;">​</a></h2><p><strong>Blueprint</strong> ／ 読み ぶるーぷりんと</p><p>Unreal Engineのノードベースのビジュアルスクリプティング機能と、それを使うアセット。Blueprint Classではコンポーネントと振る舞いを持つ再利用可能なクラスを定義できる。</p><p><strong>この分野での意味</strong>　Unityのプレハブは主にオブジェクト構成の再利用に使う。</p><p><strong>例</strong>　扉を開閉するBlueprint Classを作る。</p><p><strong>関連</strong>　<a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・Component</a> · <a href="/study/glossary/game.html#prefab">プレハブ</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/introduction-to-blueprints-visual-scripting-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Introduction to Blueprints（UE 5.8）</a></p><h2 id="frame" tabindex="-1">フレーム <a class="header-anchor" href="#frame" aria-label="Permalink to &quot;フレーム {#frame}&quot;">​</a></h2><p><strong>frame</strong> ／ 読み ふれーむ</p><p>ゲームループで処理を進める一巡や、描画して表示へ渡す画像の一枚。更新・描画・表示のどれを数えるかで意味が変わる。</p><p><strong>この分野での意味</strong>　固定tickの更新は、1フレームに0回または複数回起きることがある。</p><p><strong>例</strong>　次のフレームで入力を読み取る。</p><p><strong>関連</strong>　<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a> · <a href="/study/glossary/game.html#tick">ティック</a> · <a href="/study/glossary/graphics.html#frame">フレーム（描画）</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/execution-order.html" target="_blank" rel="noreferrer">Unity 6.3 — Event function execution order</a></p><h2 id="frame-drop" tabindex="-1">フレーム落ち <a class="header-anchor" href="#frame-drop" aria-label="Permalink to &quot;フレーム落ち {#frame-drop}&quot;">​</a></h2><p><strong>frame drop / dropped frame</strong> ／ 読み ふれーむおち</p><p>予定したタイミングに新しい絵を出せず、画像が飛んだり前の画像が表示され続けたりすること。</p><p><strong>この分野での意味</strong>　会話ではFPSが下がること全般にも使う。</p><p><strong>例</strong>　負荷が高い場面でフレーム落ちが起きる。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a> · <a href="/study/glossary/game.html#hitch">ヒッチ</a> · <a href="/study/glossary/game.html#slowdown">処理落ち</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/stat-commands-in-unreal-engine" target="_blank" rel="noreferrer">Epic Games — Stat Commands（UE 5.8）</a></p><h2 id="prefab" tabindex="-1">プレハブ <a class="header-anchor" href="#prefab" aria-label="Permalink to &quot;プレハブ {#prefab}&quot;">​</a></h2><p><strong>prefab</strong> ／ 読み ぷれはぶ</p><p>Unityで、GameObjectとそのコンポーネントや子の構成を保存し、複数の場所で使えるようにしたアセット。</p><p><strong>例</strong>　同じ敵のプレハブから3体を生成する。</p><p><strong>関連</strong>　<a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブと生成・破棄の基本</a> · <a href="/study/glossary/game.html#blueprint">ブループリント</a> · <a href="/study/glossary/game.html#spawn">スポーン</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Prefabs.html" target="_blank" rel="noreferrer">Unity 6.3 — Prefabs</a></p><h2 id="hot-path" tabindex="-1">ホットパス <a class="header-anchor" href="#hot-path" aria-label="Permalink to &quot;ホットパス {#hot-path}&quot;">​</a></h2><p><strong>hot path</strong> ／ 読み ほっとぱす</p><p>頻繁に通る処理経路や、実行時間の多くを占める経路。プロファイル結果から特定する。</p><p><strong>例</strong>　毎tick通る衝突候補の収集がホットパスだった。</p><p><strong>関連</strong>　<a href="/study/tools/profiling/cpu-profiling.html">CPUプロファイリング</a> · <a href="/study/glossary/game.html#budget">バジェット（予算）</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ProfilerCPU.html" target="_blank" rel="noreferrer">Unity 6.3 — CPU Usage Profiler module</a></p><h2 id="master-up" tabindex="-1">マスターアップ <a class="header-anchor" href="#master-up" aria-label="Permalink to &quot;マスターアップ {#master-up}&quot;">​</a></h2><p><strong>master submission / going gold</strong> ／ 読み ますたーあっぷ</p><p>製品版の基準になるビルドを確定し、提出・製造・配信の工程へ渡せる段階に達すること。</p><p><strong>この分野での意味</strong>　和製の現場語。どの段階をそう呼ぶかや、審査の前後関係はプロジェクトによる。</p><p><strong>例</strong>　提出用のビルドを確定してマスターアップした。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配信</a> · <a href="/study/glossary/game.html#build">ビルド（成果物）</a> · <a href="/study/glossary/game.html#lot-check">ロットチェック</a></p><h2 id="map" tabindex="-1">マップ <a class="header-anchor" href="#map" aria-label="Permalink to &quot;マップ {#map}&quot;">​</a></h2><p><strong>map</strong> ／ 読み まっぷ</p><p>地形や配置を含むプレイ空間。Unreal Engineでは、レベルを保存したマップファイルも指す。</p><p><strong>この分野での意味</strong>　地図UIや、プログラミングの連想コンテナを指す場合もある。</p><p><strong>例</strong>　新しい対戦マップを開く。</p><p><strong>関連</strong>　<a href="/study/game/world-streaming.html">ワールドストリーミング</a> · <a href="/study/glossary/game.html#level">レベル</a> · <a href="/study/glossary/game.html#scene">シーン</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/level-streaming-overview-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Level Streaming Overview（UE 5.8）</a></p><h2 id="asset-baking" tabindex="-1">「焼く」・アセットの「焼き」 <a class="header-anchor" href="#asset-baking" aria-label="Permalink to &quot;「焼く」・アセットの「焼き」 {#asset-baking}&quot;">​</a></h2><p><strong>asset baking / bake / burn a disc / program a ROM</strong> ／ 読み やく あせっとのやき やき やきこみ べいく</p><p>制作時の計算結果や設定を、実行時に読み取れるデータとして書き出すこと。</p><p><strong>この分野での意味</strong>　「ディスクを焼く」は光ディスクにデータを書き込むこと。「ROMを焼く」は書き込み可能なROMにプログラムなどを書き込むことを指す。</p><p><strong>例</strong>　アニメーションを頂点テクスチャに焼く。提出用のディスクを焼く。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/vertex-effects.html">頂点シェーダーでの表現</a> · <a href="/study/glossary/graphics.html#bake">ベイク（焼き込み）</a> · <a href="/study/glossary/game.html#cook">クック</a> · <a href="/study/glossary/game.html#rom">ROM（ロム）</a></p><p><strong>出典</strong>　<a href="https://www.sidefx.com/docs/houdini/nodes/out/labs--vertex_animation_textures-3.0.html" target="_blank" rel="noreferrer">SideFX — Labs Vertex Animation Textures 3.0</a> · <a href="https://support.apple.com/en-euro/guide/mac-help/mchl8addfd95/27/mac/27" target="_blank" rel="noreferrer">Apple — CDやDVDに情報を書き込む</a> · <a href="https://ww1.microchip.com/downloads/en/DeviceDoc/30274b.pdf" target="_blank" rel="noreferrer">Microchip — EPROM Memory Programming Specifications</a></p><h2 id="regression" tabindex="-1">リグレッション <a class="header-anchor" href="#regression" aria-label="Permalink to &quot;リグレッション {#regression}&quot;">​</a></h2><p><strong>regression</strong> ／ 読み りぐれっしょん でぐれ</p><p>以前は動作していた機能が、変更後に動かなくなったり悪化したりすること。</p><p><strong>この分野での意味</strong>　現場では「デグレ」とも呼ぶ。性能の悪化にも使う。</p><p><strong>例</strong>　ロードを短縮する修正でセーブ復元にリグレッションが出た。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/programming.html#regression">リグレッション</a> · <a href="/study/glossary/game.html#qa">QA</a></p><p><strong>出典</strong>　<a href="https://istqb.org/wp-content/uploads/2024/11/ISTQB_CTFL_Syllabus_v4.0.1.pdf" target="_blank" rel="noreferrer">ISTQB — Certified Tester Foundation Level Syllabus 4.0.1</a></p><h2 id="level" tabindex="-1">レベル <a class="header-anchor" href="#level" aria-label="Permalink to &quot;レベル {#level}&quot;">​</a></h2><p><strong>level</strong> ／ 読み れべる</p><p>ゲームの舞台やステージ。Unreal EngineではActorを配置する単位にも使う。</p><p><strong>この分野での意味</strong>　キャラクターの成長段階を示す「レベル」とは指すものが違う。</p><p><strong>例</strong>　常駐レベルに、街区のストリーミングレベルを重ねる。</p><p><strong>関連</strong>　<a href="/study/game/world-streaming.html">ワールドストリーミング</a> · <a href="/study/glossary/game.html#map">マップ</a> · <a href="/study/glossary/game.html#scene">シーン</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/level-streaming-overview-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Level Streaming Overview（UE 5.8）</a></p><h2 id="load" tabindex="-1">ロード <a class="header-anchor" href="#load" aria-label="Permalink to &quot;ロード {#load}&quot;">​</a></h2><p><strong>load / loading</strong> ／ 読み ろーど</p><p>ファイルや配布データを読み、必要な展開・転送・登録を経てゲームから使える状態にすること。</p><p><strong>この分野での意味</strong>　ファイルを読み終わる時刻と、ゲームから使える時刻は異なることがある。</p><p><strong>例</strong>　タイトル画面の裏で次のシーンをロードする。</p><p><strong>関連</strong>　<a href="/study/game/asset-loading.html">実行時のアセットロード</a> · <a href="/study/glossary/game.html#unload">アンロード</a> · <a href="/study/glossary/game.html#streaming">ストリーミング</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/level-streaming-overview-in-unreal-engine?lang=en-US" target="_blank" rel="noreferrer">Epic Games — Level Streaming Overview（UE 5.8）</a></p><h2 id="lot-check" tabindex="-1">ロットチェック <a class="header-anchor" href="#lot-check" aria-label="Permalink to &quot;ロットチェック {#lot-check}&quot;">​</a></h2><p><strong>Lot Check / platform compliance testing</strong> ／ 読み ろっとちぇっく</p><p>ゲーム機向けソフトが、対象機種で正常に動き、プラットフォームのガイドラインに適合するかを確認する工程。</p><p><strong>この分野での意味</strong>　任天堂が公に用いる工程名。プラットフォームごとに審査名と要件は変わる。</p><p><strong>例</strong>　対応する実機で中断・復帰を確認してロットチェックに備える。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#trc">TRC</a> · <a href="/study/glossary/game.html#master-up">マスターアップ</a></p><p><strong>出典</strong>　<a href="https://www.nintendo.co.jp/jobs/keyword/154.html" target="_blank" rel="noreferrer">任天堂 — ゲームソフト適合性検査とロットチェック</a></p><h2 id="rom" tabindex="-1">ROM（ロム） <a class="header-anchor" href="#rom" aria-label="Permalink to &quot;ROM（ロム） {#rom}&quot;">​</a></h2><p><strong>ROM / Read-Only Memory</strong> ／ 読み ろむ あーるおーえむ</p><p>本来は読み出し専用のメモリ。ゲーム制作の会話では、試遊や検査に使うビルド一式を「ロム」と呼ぶこともある。</p><p><strong>この分野での意味</strong>　「今日のロム」「開発中のロム」のような用法では、媒体の種類より、試遊や検査に使うビルドの版を指す。</p><p><strong>例</strong>　今日のロムを実機で確認する。</p><p><strong>関連</strong>　<a href="/study/history/video-games.html">ビデオゲーム史</a> · <a href="/study/glossary/game.html#build">ビルド（成果物）</a></p><p><strong>出典</strong>　<a href="https://www.nintendo.co.jp/wiiu/interview/hardware/vol12/index.html" target="_blank" rel="noreferrer">任天堂 — 社長が訊く Wii Street U（制作現場での「ROM」）</a> · <a href="https://www.gamer.ne.jp/news/202512140001/" target="_blank" rel="noreferrer">カプコン開発者による『プラグマタ』の合同インタビュー（Gamer）</a> · <a href="https://csrc.nist.gov/glossary/term/read_only_memory" target="_blank" rel="noreferrer">NIST — Read-Only Memory</a></p><h2 id="workflow" tabindex="-1">ワークフロー <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;ワークフロー {#workflow}&quot;">​</a></h2><p><strong>workflow</strong> ／ 読み わーくふろー</p><p>作業を完了するまでの手順と受け渡しの流れ。人による確認、判断、差し戻しも含められる。</p><p><strong>例</strong>　レビュー後にテクスチャを差し替えるワークフローを決める。</p><p><strong>関連</strong>　<a href="/study/glossary/game.html#pipeline">パイプライン（制作）</a> · <a href="/study/glossary/game.html#toolchain">ツールチェーン</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/AssetWorkflow.html" target="_blank" rel="noreferrer">Unity 6.3 — Introduction to assets</a></p>',353)])])}const c=a(n,[["render",s]]);export{d as __pageData,c as default};
